    private void acneClassifier()throws Exception{Bitmap image=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);image.eraseColor(0xffc39f87);image.setPixel(64,64,0xffcd877d);image.setPixel(200,150,0xff9f7b63);int n=cls("ncp.PhotoPortrait$BodySkinMask").getField("SIZE").getInt(null);byte[] coverage=new byte[n*n];Arrays.fill(coverage,(byte)255);Object skin=cls("ncp.PhotoPortrait$BodySkinMask").getConstructor(byte[].class).newInstance((Object)coverage);try{List<?> found=(List<?>)stat("cc.huevia.album.PhotoAutoBlemishes","detect",image,skin,Collections.emptyList(),(BooleanSupplier)()->false);boolean red=false,dark=false;for(Object h:found){double tx=((Number)get(h,"tx")).doubleValue(),ty=((Number)get(h,"ty")).doubleValue();if(Math.hypot(tx-.25,ty-.25)<.025)red=true;if(Math.hypot(tx-200.5/256,ty-150.5/256)<.025)dark=true;}check("red-micro-blemish-proposed",red);check("neutral-dark-beauty-mark-preserved",!dark);}finally{image.recycle();}}
